// Charts of the newer types (chartex: waterfall, funnel, histogram, box and
// whisker, treemap, sunburst) and surface charts are drawn, in a workbook and
// in a document: no placeholder, and the colours they are drawn in are there.
// A region map, which needs map data, shows the fallback of its alternate
// content.
//
// No screenshots: the pixels of the canvas are read with getImageData().
// Every file is generated by code (test/chartex-fixtures.ts). The chart of a
// workbook stands within columns A to D (header 72 x 22, columns 64 wide, rows
// 20 high), so that a phone shows all of it.
import type { Page } from '@playwright/test';
import { catAx, chartFrameOf, chartWorkbook, chartXml, group, numLit, ser, sheetData, solid, spPr, strLit, valAx } from '../test/chart-fixtures';
import { addChartEx, anchor, CHARTEX_REL, chartExFrame, chartExRun, chartExXml, data, NS_CX1, numDim, series, seriesName, strDim, treemapXml, waterfallXml } from '../test/chartex-fixtures';
import { p } from '../test/doc-layout-fixtures';
import { docx } from './fixtures/docx';
import { expect, test } from './helpers';

/** The accent colours of the theme of the generated files (those of Office). */
const ACCENT1 = [68, 114, 196];
const ACCENT2 = [237, 125, 49];
const ACCENT3 = [165, 165, 165];
const GREEN = [0, 176, 80];
const RED = [192, 0, 0];
const PLACEHOLDER = [241, 243, 244];
/** The frame of the chart on the canvas, CSS pixels: A6 to the start of E19. */
const FRAME = { x: 72, y: 22 + 5 * 20, width: 4 * 64, height: 13 * 20 };
/** The cells the waterfall of waterfallXml() reads (Sayfa1!A2:B6, a header above). */
const CELLS = sheetData([
  ['Ad', 'Değer'],
  ['Start', 100],
  ['Q1', 20],
  ['Q2', -50],
  ['Q3', 30],
  ['End', 100],
]);
/**
 * The cells the treemap of treemapXml() reads: the levels in Sayfa1!A2:C7 (the outermost first, the
 * leaves last) and the sizes in D2:D7. A series reads its cells, not what its part cached: a chart
 * over empty cells is drawn empty, as Excel draws it.
 */
const TREE_CELLS = sheetData([
  ['Kök', 'Orta', 'Yaprak', 'Boyut'],
  ['Kök', 'A', 'a1', 10],
  ['Kök', 'A', 'a2', 20],
  ['Kök', 'B', 'b1', 30],
  ['Kök', 'B', 'b2', 5],
  ['Diğer', 'C', 'c1', 15],
  ['Diğer', 'C', 'c2', 20],
]);

const bookOf = async (xml: string, cells = CELLS) => addChartEx(await chartWorkbook({ sheet: cells, drawing: anchor(chartExFrame('rIdX1'), [0, 5], [4, 18]), charts: [] }), [xml]);

async function mount(page: Page, bytes: Uint8Array): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64 }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, { locale: 'en-US' });
    },
    { base64: Buffer.from(bytes).toString('base64') },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', `return ${code}`)((window as any).__view), code);

/** Pixels of a colour in the frame of the chart (or in the whole canvas), and the share of the box they cover, after a forced redraw. */
function ink(page: Page, colour: number[], box: { x: number; y: number; width: number; height: number } | null = FRAME): Promise<{ count: number; share: number }> {
  return page.evaluate(
    ([colour, box]) => {
      const view = (window as any).__view;
      view.render();
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const x = box ? Math.round(box.x * dpr) : 0;
      const y = box ? Math.round(box.y * dpr) : 0;
      const width = box ? Math.round(box.width * dpr) : canvas.width;
      const height = box ? Math.round(box.height * dpr) : canvas.height;
      const data = canvas.getContext('2d')!.getImageData(x, y, width, height).data;
      const [r, g, b] = colour as number[];
      let count = 0;
      for (let i = 0; i < data.length; i += 4) if (Math.abs(data[i] - r) <= 3 && Math.abs(data[i + 1] - g) <= 3 && Math.abs(data[i + 2] - b) <= 3) count++;
      return { count, share: count / (width * height) };
    },
    [colour, box] as [number[], typeof box],
  );
}

async function noPlaceholder(page: Page): Promise<void> {
  expect(await view(page, 'view.getDrawingState().objects')).toBe(1);
  const grey = await ink(page, PLACEHOLDER);
  expect(grey.share, 'the grey of a placeholder').toBeLessThan(0.01);
}

test.describe('charts of the newer types in a workbook', () => {
  test('a waterfall is drawn: bars of increase, decrease and total in their colours', async ({ page }) => {
    await mount(page, await bookOf(waterfallXml()));
    await noPlaceholder(page);
    for (const colour of [ACCENT1, ACCENT2, ACCENT3]) expect((await ink(page, colour)).count).toBeGreaterThan(20);
    const state = await view(page, 'view.getChartState()');
    expect(state.texts).toContain('Increase');
    expect(state.texts).toContain('Q2');
  });

  const funnel = chartExXml({
    data: data(0, strDim(undefined, [['a', 'b', 'c']]) + numDim(undefined, [30, 20, 10])),
    series: series({ layout: 'funnel', dataId: 0, inner: seriesName('Huni') + `<cx:spPr>${solid('00B050')}</cx:spPr>` }),
  });
  const histogram = chartExXml({
    data: data(0, numDim(undefined, [1, 2, 2, 3, 3, 3, 4, 4, 5, 9])),
    series: series({ layout: 'clusteredColumn', dataId: 0, inner: `<cx:spPr>${solid('00B050')}</cx:spPr>`, layoutPr: '<cx:binning intervalClosed="r"><cx:binSize val="2"/></cx:binning>' }),
  });
  const box = chartExXml({
    data: data(0, numDim(undefined, [2, 4, 4, 5, 7, 9, 10, 12, 30])),
    series: series({ layout: 'boxWhisker', dataId: 0, inner: `<cx:spPr>${solid('00B050')}</cx:spPr>` }),
  });
  // Each kind on its own, so that one that fails does not hide the others. A treemap and a sunburst colour their
  // largest branch ("Kök", 65 of 100) with the first accent colour.
  for (const [label, xml, colour, cells] of [
    ['treemap', treemapXml(), ACCENT1, TREE_CELLS],
    ['sunburst', treemapXml('sunburst', ''), ACCENT1, TREE_CELLS],
    ['funnel', funnel, GREEN, CELLS],
    ['histogram', histogram, GREEN, CELLS],
    ['box and whisker', box, GREEN, CELLS],
  ] as [string, string, number[], string][]) {
    test(`a ${label} is drawn in the colour of its series`, async ({ page }) => {
      await mount(page, await bookOf(xml, cells));
      await noPlaceholder(page);
      expect((await ink(page, colour)).count, label).toBeGreaterThan(200);
    });
  }

  test('a region map shows the fallback of its alternate content', async ({ page }) => {
    const map = chartExXml({ data: data(0, strDim(undefined, [['Türkiye']]) + numDim(undefined, [1])), series: series({ layout: 'regionMap', dataId: 0 }) });
    await mount(page, await bookOf(map));
    expect(await view(page, 'view.getDrawingState().objects')).toBe(1);
    expect((await ink(page, PLACEHOLDER)).share).toBeLessThan(0.01);
    expect((await view(page, 'view.getChartState()')).charts).toBe(0);
  });

  test('a surface chart is drawn from above in the colours of its bands', async ({ page }) => {
    const rows = [
      [0, 5, 10],
      [5, 10, 15],
      [10, 15, 20],
    ];
    const surface = chartXml({
      plot:
        group(
          'surfaceChart',
          '',
          rows.map((values, i) => ser(i, { cat: strLit(['x', 'y', 'z']), val: numLit(values) })).join(''),
          `<c:bandFmts><c:bandFmt><c:idx val="0"/>${spPr(solid('00B050'))}</c:bandFmt><c:bandFmt><c:idx val="1"/>${spPr(solid('C00000'))}</c:bandFmt></c:bandFmts>`,
        ) +
        catAx() +
        valAx('<c:majorUnit val="10"/>', '<c:orientation val="minMax"/><c:max val="20"/><c:min val="0"/>'),
    });
    await mount(page, await chartWorkbook({ sheet: CELLS, drawing: anchor(chartFrameOf('rIdC1'), [0, 5], [4, 18]), charts: [surface] }));
    await noPlaceholder(page);
    const green = await ink(page, GREEN);
    const red = await ink(page, RED);
    expect(green.count).toBeGreaterThan(200);
    expect(red.count).toBeGreaterThan(200);
  });
});

test.describe('charts of the newer types in a document', () => {
  test('a chart of a newer type is drawn in place of the fallback of its alternate content', async ({ page }) => {
    const run = chartExRun('rIdX1', 300, 200).replace('<mc:Choice Requires="cx1">', `<mc:Choice xmlns:cx1="${NS_CX1}" Requires="cx1">`);
    const bytes = await docx(p(run) + p('Below the chart'), { rels: [['rIdX1', CHARTEX_REL, 'charts/chartEx1.xml']], parts: [['word/charts/chartEx1.xml', treemapXml()]] });
    await page.goto('/e2e/pages/doc.html');
    await expect(page.locator('#state')).toHaveText('ready');
    await page.evaluate((input) => (window as any).__mountDoc(input, { zoom: 1 }), Array.from(bytes));
    await page.waitForFunction(() => (window as any).__docView.layoutDone === true, undefined, { timeout: 60_000 });
    await page.evaluate(() => new Promise<void>((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve()))));
    const found = await page.evaluate((colour) => {
      const canvas = document.querySelector('#host .bym-doc-page[data-page="1"] canvas') as HTMLCanvasElement;
      const pixels = canvas.getContext('2d')!.getImageData(0, 0, canvas.width, canvas.height).data;
      let count = 0;
      for (let i = 0; i < pixels.length; i += 4) if (Math.abs(pixels[i] - colour[0]) <= 6 && Math.abs(pixels[i + 1] - colour[1]) <= 6 && Math.abs(pixels[i + 2] - colour[2]) <= 6) count++;
      return count;
    }, ACCENT1);
    expect(found, 'the first branch of the treemap').toBeGreaterThan(500);
    expect((await page.evaluate(() => (window as any).__docView.getChartState())).charts).toBe(1);
  });
});
